function formEmail(value) {
  const email = typeof value === "string" ? value.trim().toLowerCase() : "";
  if (
    email.length > 254 ||
    !/^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+@(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/.test(
      email,
    )
  ) {
    throw new Error("A business email address is required");
  }
  return email;
}
return [{ json: { email: formEmail($input.first().json["Business email"]) } }];

function verify({ email, result }) {
  const status = result?.status;
  if (typeof status !== "string") throw new Error("Hunter did not return a verification status");
  if (status !== "valid") return { valid: false };
  if (typeof result.email !== "string" || result.email.toLowerCase() !== email.toLowerCase()) {
    throw new Error("Hunter verification does not match the submitted email");
  }
  return { valid: true };
}

const email = $("Read the business email").first().json.email;
return verify({ email, result: $input.first().json.data }).valid ? [{ json: { email } }] : [];

function matchHunterLead({ email, enrichment }) {
  const person = enrichment?.data?.person;
  const company = enrichment?.data?.company;
  const domain = email.slice(email.lastIndexOf("@") + 1);
  const normalized = (value) => (typeof value === "string" ? value.trim().toLowerCase() : "");
  const skip = { ready: false, properties: {}, filterGroups: [] };
  if (
    !person ||
    !company ||
    person.fuzzy === true ||
    normalized(person.email) !== email ||
    normalized(person.employment?.domain) !== domain ||
    normalized(company.domain) !== domain
  )
    return skip;

  const clean = (value) => (typeof value === "string" ? value.trim() : "");
  const count = company.metrics?.employeesCount;
  const range = clean(company.metrics?.employees);
  const size =
    Number.isSafeInteger(count) && count >= 0
      ? String(count)
      : /^\d+(?:-\d+|\+)?$/.test(range)
        ? range
        : "";
  const values = {
    firstname: clean(person.name?.givenName),
    lastname: clean(person.name?.familyName),
    jobtitle: clean(person.employment?.title),
    company: clean(person.employment?.name) || clean(company.name),
    hunter_company_size: size,
  };
  const fields = Object.entries(values).filter(([, value]) => value !== "");
  if (fields.length === 0) return skip;
  return {
    ready: true,
    properties: { email, ...Object.fromEntries(fields) },
    filterGroups: [{ filters: [{ propertyName: "email", operator: "EQ", value: email }] }],
  };
}
const mapped = matchHunterLead({
  email: $("Read the business email").first().json.email,
  enrichment: $input.first().json,
});
return mapped.ready ? [{ json: mapped }] : [];

function verifyContactReceipt(record, email, expectedId) {
  const id = record?.id;
  if (
    typeof id !== "string" ||
    !/^[1-9]\d*$/.test(id) ||
    record.archived === true ||
    (expectedId && expectedId !== "0" && id !== expectedId) ||
    typeof record.properties?.email !== "string" ||
    record.properties.email.toLowerCase() !== email
  ) {
    throw new Error("HubSpot did not confirm the submitted contact");
  }
  return id;
}
function chooseContact({ search, email }) {
  const records = search?.results ?? search?.records ?? search?.objects ?? search?.items;
  if (
    !Array.isArray(records) ||
    records.length > 1 ||
    search.paging?.next ||
    search.paging?.nextAfter ||
    (typeof search.total === "number" && search.total !== records.length)
  ) {
    throw new Error("HubSpot did not return a unique contact lookup");
  }
  return records.length
    ? { recordId: verifyContactReceipt(records[0], email), exists: true }
    : { recordId: "0", exists: false };
}
return [
  {
    json: chooseContact({
      search: $input.first().json,
      email: $("Read the business email").first().json.email,
    }),
  },
];

function verifyContactReceipt(record, email, expectedId) {
